  ('f64d5c1f-f0df-41a6-8820-8687c771bb84', '206d70cf-eedc-4bea-94d5-1d11b6fe6247',
   'be9ec6b2-bdda-4b5a-b939-7a50fdc12e9a', 'Rondo 4 contre 1 · lever la tête avant de recevoir',
