  ('c8296654-ced8-4504-b6e2-32b7104960cb', '206d70cf-eedc-4bea-94d5-1d11b6fe6247',
   '66843952-d29c-40fa-b7b3-943af252e1cc', 'Sortie de pressing · perdre, réagir, ressortir',
