:{"x":58,"y":48}}}],"legend":[{"label":"Zone à occuper","color":"#38BDF8"},{"label":"Pressing","color":"#E34948"}]}'::jsonb, 1, '7e0eaa16-951d-47bf-81bf-175a7324554e'),
  ('beeecd30-fd45-4db9-806c-2e09b4fe5418', '206d70cf-eedc-4bea-94d5-1d11b6fe6247',
   '588c7a10-1e97-4a6c-90fb-7320a1608cec', 'Jeu des quatre portes · changer de cible',
   '{"version":1,"field":{"kind":"CUSTOM","lengthM":30,"widthM":25,"orientation":"HORIZONTAL"},"alt":"Terrain de 30 × 25 mètres avec quatre petites portes, une par côté. Quatre joueurs violets contre quatre rouges : marquer dans n''importe quelle porte, ce qui oblige à regarder des deux côtés.","elements":[{"id":"p1","kind":"GOAL","size":"MINI","rotation":90,"x":4,"y":30},{"id":"p2","kind":"GOAL","size":"MINI","rotation":90,"x":4,"y":70},{"id":"p3","kind":"GOAL","size":"MINI","rotation":90,"x":96,"y":30},{"id":"p4","kind":"GOAL","size":"MINI","rotation":90,"x":96,"y":70},{"id":"a1","kind":"PLAYER","team":"A","number":1,"x":30,"y":25},{"id":"a2","kind":"PLAYER","team":"A","number":2,"x":30,"y":75},{"id":"a3","kind":"PLAYER","team":"A","number":3,"x":55,"y":50},{"id":"b1","kind":"PLAYER","team":"B","number":4,"x":45,"y":30},{"id":"b2","kind":"PLAYER","team":"B","number":5,"x":45,"y":70},{"id":"b3","kind":"PLAYER","team":"B","number":6,"x":70,"y":50},{"id":"ball","kind":"BALL","x":34,"y":27},{"id":"t1","kind":"TEXT","text":"Toutes les portes comptent","x":50,"y":6}],"keyframes":[{"t":0,"phase":"POSSESSION","caption":"Quatre cibles : la tête tourne avant le pied","positions":{"ball":{"x":34,"y":27},"a3":{"x":55,"y":50}}},{"t":0.5,"phase":"TRANSITION","caption":"Les rouges ferment un côté : on attaque l''autre","positions":{"ball":{"x":40,"y":62},"a2":{"x":38,"y":66},"a3":{"x":62,"y":44},"b2":{"x":48,"y":60}}},{"t":1,"phase":"POSSESSION","caption":"La porte la plus éloignée est la plus libre","positions":{"ball":{"x":88,"y":68},"a2":{"x":70,"y":70},"a3":{"x":74,"y":40},"b2":{"x":62,"y":58}}}],"legend":[{"label":"Porte : on marque des deux sens","color":"#0B0A14"}]}'::jsonb, 2, '7e0eaa16-951d-47bf-81bf-175a7324554e');
